const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_3","ls":"6.3","title":"Lernpfadübung · LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","version":"1.0","source":"Fachbereiche/BFSdual/LF06/LS_6_3_Fachgeschaeft_gestalten.md"};
const COMP=[["Fachkompetenz","Ich plane eine kleine Beratungsfläche. Ich begründe, welche Artikel ich zusammen zeige. Ich erkläre, wie man die Artikel gut erreicht und am Fahrrad zeigen kann."],["Personalkompetenz","Ich ändere meinen Entwurf, wenn er bei der Beratung zu Problemen führt."],["Sozialkompetenz","Ich bespreche mit anderen, welche Wege die Kundschaft und das Verkaufspersonal brauchen."],["Methodenkompetenz","Ich übertrage Maße in eine Skizze oder ein Modell. Damit vergleiche ich zwei Anordnungen."],["Medienkompetenz","Ich beschrifte den Plan und erkläre die Zeichen in einer Legende. So können andere ihn lesen."]];
const BANK=[{"title":"Wenn zwei Fahrräder zusammentreffen","scene":"Bei Block möchte eine Kundin sehen, wie die Halterung eines Lichts am Lenker sitzt. Gleichzeitig kommt ein zweiter Kunde mit seinem Rad durch denselben Bereich.","ask":"Welche Aussagen beschreiben die Situation?","options":["Die Verkäuferin bringt ein Musterlicht.","Der zweite Kunde kommt ohne Fahrrad.","Beide Personen halten mit ihren Rädern an.","Die Kundin testet die Minipumpe ohne Hilfe.","Die Vorführung und der Weg des zweiten Kunden beanspruchen denselben Bereich.","Die Ladenleitung hat den Aufbau bereits getestet."],"answer":[0,2,4],"why":"Das Musterlicht soll am Rad gezeigt werden. Als ein zweites Rad durch denselben Bereich kommt, halten beide an. Der Aufbau wird erst am nächsten Vormittag getestet.","hint":"Schau auf den Augenblick, in dem die Verkäuferin zurückkommt.","steps":"Trenne, wer welches Rad bewegt und was die Verkäuferin mitbringt.","example":"Ein Beispiel für zwei gleichzeitige Handlungen ist Greifen ins Regal und Vorbeischieben am Regal.","c":2,"sourceRefs":["Handlungssituation"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Sichtweisen auf dieselbe Fläche","scene":"Sebastian Wolf und Christian Klein arbeiten bei Global Bike. Beide achten bei der Aktion auf verschiedene Teile eines praktikablen Aufbaus.","ask":"Was wollen die beiden im Fall erreichen?","options":["Christian möchte die Werkstatt an einen anderen Platz verlegen.","Sebastian möchte, dass mehr Platz für die Vorführung am Rad da ist.","Christian achtet auf den Zugriff auf die verpackte Ware.","Sebastian möchte das Zubehör nur auf Schildern erklären.","Christian will zwei andere Zubehörartikel bestellen.","Sebastian möchte den Beratungstresen als Vorführplatz nutzen."],"answer":[1,2],"why":"Sebastian achtet auf Platz am Rad. Christian achtet darauf, dass das Personal die verpackte Ware auch während der Beratung erreicht.","hint":"Lies nach, worauf jede Person im Fall direkt hinweist.","steps":"Ordne die Aussagen zu Vorführung oder Warenzugriff.","example":"Eine Beratung kann am Vorführrad beginnen und mit dem Griff zur Verpackung enden.","c":2,"sourceRefs":["Handlungssituation","M2"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was für den Aufbau bereitsteht","scene":"Die Ladenleitung will den Aufbau am nächsten Vormittag ausprobieren. Regale und Tisch stehen für den Versuch bereit.","ask":"Welche Dinge sind bewegliche Warenträger der Aktion?","options":["Das Vorführrad.","Der feste Beratungstresen.","Das erste Rollregal.","Der eingezeichnete Platz zum Vorführen.","Das zweite Rollregal.","Der schmale Tisch."],"answer":[2,4,5],"why":"Block nutzt zwei bewegliche Rollregale und einen schmalen Tisch als Warenträger. Das Vorführrad dient als Modell, der Tresen bleibt fest und der Vorführplatz braucht freien Boden.","hint":"Warenträger sind die Möbel für die Aktionsware.","steps":"Unterscheide bewegliche Möbel, feste Möbel und freie Flächen.","example":"Auf einen Warenträger kannst du verpackte Ware stellen.","c":0,"sourceRefs":["Handlungssituation","M2","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zugriffsseiten lesbar markieren","scene":"Die lange Bedienseite des Rollregals ist im Plan mit einem Pfeil markiert. Ein zweiter Pfeil soll den Weg zur Werkstatt zeigen.","ask":"Welche Darstellungen helfen, die beiden Bedeutungen auseinanderzuhalten?","options":["Den Zugriffspfeil direkt an die lange Seite des Rollregals setzen.","Die Bedeutung beider Pfeile unter „Aktion“ zusammenfassen.","Die Bedienseite am Nordpfeil des Grundrisses ablesen lassen.","Für den Werkstattweg und die Bedienseite unterschiedliche Zeichen in der Legende erklären.","Den ganzen Gang als Möbel markieren.","Den Pfeil zum Regal auf das nächste Produktfoto setzen."],"answer":[0,3],"why":"Der Ort des Zeichens zeigt, welche Regalseite gemeint ist. Die Legende unterscheidet den Zugriff am Regal vom Weg zur Werkstatt.","hint":"Welches Zeichen zeigt einen Ort, welches eine Richtung durch den Laden?","steps":"Prüfe Zeichen, Lage im Plan und Legende getrennt.","example":"Ein kurzer Pfeil direkt aufs Regal kann die Bedienseite zeigen. Eine Linie entlang des Gangs kann für einen Weg stehen.","c":4,"sourceRefs":["M1","M2","M4"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Muster, zwei Zwecke","scene":"Block stellt ein Vorführrad bereit. Für einige Produkte gibt es außerdem ein Muster.","ask":"Welche Zuordnungen stimmen?","options":["Der Flächenplan ist das Vorführmodell für das Zubehör.","Das Vorführrad dient als Modell für die Demonstration.","Ein Muster ist die für die Aktion reservierte Stelle im Gang.","Ein Muster des Lichtsets kann beim Ansetzen der Halterung benutzt werden.","Die Luft im Reifen ist das Muster für die Minipumpe.","Ein leeres Taschenmuster kann man anfassen und öffnen."],"answer":[1,3,5],"why":"Das Rad ist das Modell, an dem etwas gezeigt wird. Licht und Tasche sind Muster der eigentlichen Produkte. Die Kundschaft kann die Funktion oder Handhabung daran ausprobieren.","hint":"Unterscheide den Artikel, den du zeigst, und den Gegenstand, an dem du ihn zeigst.","steps":"Ordne je ein Beispiel dem Vorführmodell, dem Muster oder dem Plan zu.","example":"Ein Lenker ist Teil des Vorführmodells. Die daran angesetzte Halterung ist Zubehör.","c":0,"sourceRefs":["M2","M3","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zonen im Grundriss einordnen","scene":"M1 zeigt den Hauptdurchgang links von x = 0,00 bis x = 1,20 m. Die Aktionsfläche beginnt bei x = 1,20 m und liegt oberhalb von y = 0,80 m. Der feste Tresen liegt bei x = 3,60–4,80 m und y = 0,80–1,50 m.","ask":"Welche Angaben helfen, die Flächen für zwei Entwürfe gleich einzuzeichnen?","options":["Die linke Gangfläche in voller Breite bis zur Werkstatt markieren.","Die Aktionsfläche schon bei x = 0,00 m beginnen lassen.","Die Grenze bei x = 1,20 m in beiden Skizzen an derselben Stelle setzen.","Den Tresen bei jedem neuen Entwurf an eine beliebige Stelle zeichnen.","Den festen Tresen in beiden Plänen an seinen angegebenen Koordinaten belassen.","Den Hauptdurchgang nur als Punkt am Werkstatteingang einzeichnen."],"answer":[0,2,4],"why":"Hauptdurchgang, Aktionsflächengrenze und Tresen ändern sich zwischen den Entwürfen nicht. Mit denselben Referenzflächen lassen sich die Anordnungen vergleichen.","hint":"Unterscheide feste Flächen und bewegliche Warenträger.","steps":"Übertrage die x- und y-Werte zuerst in beide Skizzen. Vergleichsgrößen sollen sich beim Entwerfen nicht verschieben.","example":"Hat ein Punkt den festen x-Wert 1,20 m, liegt er von der linken Plankante aus immer gleich weit rechts.","c":3,"sourceRefs":["M1","M2"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ersten Warenplatz für ein schweres Schloss hinterfragen","scene":"Übungsvariante: Du hast das Bügelschloss S20 zuerst oben im Regal eingezeichnet, damit man es gut sieht. In M3 liest du, dass es wegen seines Gewichts unten stehen soll.","ask":"Wie gehst du mit deinem eigenen Vorschlag um?","options":["Beim bisherigen Vorschlag bleiben, weil er schon eingezeichnet ist.","Das Schloss in die untere Regalzone einplanen.","Die neue Platzierung mit der Vorgabe zum Gewicht begründen und den Zugriff prüfen.","Nur den Produktcode am oberen Platz ändern.","Das Schloss aus dem festgelegten Sortiment streichen.","Die Beratung zum Schloss auf den Hauptdurchgang verlegen."],"answer":[1,2],"why":"Der erste Entwurf darf sich ändern, sobald eine Anforderung dagegen spricht. Das Gewicht bestimmt beim Schloss die Regalzone. Der Platz unten muss erreichbar bleiben.","hint":"Vergleiche die zuerst gewählte Höhe mit der Artikelvorgabe.","steps":"Entscheide, was sich ändern muss, und begründe den Eingriff aus M3.","example":"Eine Änderung des Entwurfs lässt sich mit einer konkreten Eigenschaft des Artikels begründen.","c":1,"sourceRefs":["M2","M3","M5"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Musterlicht und Lichtschachteln","scene":"Die Kundin möchte die Halterung sehen und sich zeigen lassen, wie sie das Licht wieder löst.","ask":"Was muss die Anordnung für L10 leisten?","options":["Ein Musterlicht ist am Vorführplatz verfügbar.","Alle Lichtschachteln gehören auf den Boden neben dem Rad.","Die Verkäuferin kommt auch während der Beratung an die verpackten Lichtsets.","Das Lichtset wird neben dem Eingang im Hauptdurchgang aufbewahrt.","Um Ware zu greifen, muss die Vorführung grundsätzlich beendet werden.","Die Halterung lässt sich am Lenker zeigen."],"answer":[0,2,5],"why":"Muster am Vorführplatz und erreichbare Schachteln erfüllen unterschiedliche Zwecke. Die Halterung kann am Lenker angesetzt und wieder gelöst werden.","hint":"Suche in M3 nach zwei getrennten Angaben zu L10.","steps":"Prüfe erst, was die Kundin ausprobieren will, dann, was das Personal verkaufen können soll.","example":"Das abgesteckte freie Rechteck zum Vorführen braucht keine Schachteln auf dem Boden.","c":0,"sourceRefs":["M3"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welche Frage gehört zu welchem Artikel?","scene":"Die Kundschaft fragt zu den Aktionsartikeln nach Handhabung und Eignung.","ask":"Welche Zuordnungen stimmen?","options":["T30 Rahmentasche: Komme ich gut an meine Kleinteile?","P50 Minipumpe: Wie löse ich das Licht von der Halterung?","R40 Sattelüberzug: Kann ich ihn am Sattel ausprobieren?","S20 Bügelschloss: Passt der Pumpenkopf zum Ventil?","P50 Minipumpe: Wie setze ich sie am Ventil an?","L10 LED-Lichtset: Wie groß ist der Bügel?"],"answer":[0,2,4],"why":"Zugriff auf Kleinteile gehört zur Rahmentasche, der Sitz am Sattel zum Sattelüberzug und das Ansetzen am Ventil zur Minipumpe.","hint":"Vergleiche die Stelle am Rad oder die Nutzung je Artikel.","steps":"Unterstreiche in jeder Frage das Wort, das die Nutzung verrät.","example":"Greifen, befestigen und aufpumpen beschreiben unterschiedliche Tätigkeiten.","c":0,"sourceRefs":["M3"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Maßstab im Flächenplan","scene":"Im Plan wird der Verkaufsbereich im Maßstab 1:20 gezeichnet. Der wirkliche Bereich misst 4,80 m × 4,00 m.","ask":"Welche Aussagen sind richtig?","options":["4,80 m werden im Plan zu 12 cm.","Bei 1:20 entspricht 1 cm im Plan 20 cm im Laden.","4,00 m werden im Plan zu 20 cm.","Die 4,80 m sind im Plan 24 cm breit.","Die Werte aus dem Laden werden für den Plan verdoppelt.","1 cm im Plan entspricht 2 m im Laden."],"answer":[1,2,3],"why":"Für den Plan rechnest du die Wirklichkeit zuerst in Zentimeter um und teilst dann durch 20. 480 cm ergeben 24 cm, 400 cm ergeben 20 cm.","hint":"Schreib beide wirklichen Maße zunächst in Zentimetern.","steps":"Teile jedes Zentimetermaß durch 20 und kontrolliere die Zuordnung von Breite und Tiefe.","example":"Bei 1:20 werden aus 200 cm im Laden 10 cm auf dem Papier.","c":3,"sourceRefs":["M1"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was andere im Plan erkennen sollen","scene":"Das Team reicht einen Flächenplan ein. Ein anderes Team soll ihn prüfen, ohne euch vorher fragen zu müssen.","ask":"Welche Angaben helfen dabei?","options":["Maße von Flächen und Wegen.","Eine Legende, die die Zeichen erklärt.","Ein Produktfoto allein ohne Standort im Plan.","Beschriftete Artikel und markierte Bedienseiten.","Ein Preisrabatt statt der Platzierung von L10.","Eine unbeschriftete Linie für alle Wege und Grenzen."],"answer":[0,1,3],"why":"Maße, verständliche Zeichen und benannte Warenplätze oder Bedienseiten machen den Plan ohne mündliche Ergänzung prüfbar.","hint":"Stell dir vor, du liest den Plan zum ersten Mal.","steps":"Prüfe, ob andere anhand der Angabe messen, etwas finden oder ein Zeichen verstehen können.","example":"Eine gestrichelte Linie kann einen freien Weg markieren, wenn die Legende das erklärt.","c":4,"sourceRefs":["M1","M4","M5"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Wann ein guter Entwurf geändert wird","scene":"Im ersten Test stehen die Waren wie vorgesehen. Beim Vorführen steht ein Vorderrad vor der Bedienseite.","ask":"Welche Reaktionen passen zur Aufgabe?","options":["Die Probe als erfolgreich eintragen, weil die Möbel in die Aktionsfläche passen.","Die blockierte Stelle im Plan markieren.","Nur die Farbe für den Hauptdurchgang ändern.","Den Aufbau so anpassen, dass die Bedienseite beim Vorführen nutzbar bleibt.","Die Vorführung erneut mit einem zweiten Rad prüfen.","Das Schloss höher stellen, obwohl der Zugriff am Lichtregal blockiert ist."],"answer":[1,3,4],"why":"Markiere das beobachtete Problem, passe die Anordnung an und wiederhole die Beratungsszene. So zeigt die zweite Probe, ob die Änderung den Zugriff verbessert.","hint":"Schau auf die Ursache der Blockade und auf den Nachweis einer Verbesserung.","steps":"Ordne die sinnvollen Schritte als beobachten, ändern, erneut prüfen.","example":"Eine geänderte Farbe hilft beim Lesen. Ein Vorderrad vor dem Regal braucht eine Änderung der Anordnung.","c":1,"sourceRefs":["M2","M4","M5"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Rechteck für die Vorführung","scene":"Übungsvariante: Drei freie Rechtecke sind 2,10 m × 1,25 m, 1,30 m × 2,00 m und 1,95 m × 1,40 m groß. Die Regel fordert mindestens 2,00 m × 1,30 m. Keine andere Fläche wird dabei belegt.","ask":"Welche Prüfaussagen stimmen?","options":["2,10 m × 1,25 m reicht aus, weil das Rechteck länger als 2,00 m ist.","1,30 m × 2,00 m reicht aus, wenn die Orientierung im Grundriss passt.","1,95 m × 1,40 m reicht aus, weil die Fläche insgesamt größer ist.","2,10 m × 1,25 m ist um 0,05 m zu schmal.","1,95 m × 1,40 m ist an der langen Seite um 0,05 m zu kurz.","Ein hochkant gezeichnetes Rechteck ist grundsätzlich unzulässig."],"answer":[1,3,4],"why":"Beide Seiten müssen ihr Mindestmaß erreichen. Die lange Seite darf in x- oder y-Richtung liegen. Mehr Platz auf einer Seite gleicht ein fehlendes Maß auf der anderen Seite nicht aus.","hint":"Ordne jedem Rechteck seine längere und kürzere Seite zu.","steps":"Vergleiche jede lange Seite mit 2,00 m und jede kurze mit 1,30 m.","example":"Ein freier Bereich kann groß wirken, obwohl ein Maß für das Fahrrad fehlt.","c":3,"sourceRefs":["M2"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Wie breit ist der Weg in Wirklichkeit?","scene":"Übungsvariante: In zwei Plänen im Maßstab 1:20 sind die engsten Stellen zum Vorführplatz 4,2 cm und 4,5 cm breit. Der erforderliche Weg ist überall mindestens 0,90 m breit.","ask":"Welche Aussagen stimmen?","options":["4,2 cm entsprechen 0,84 m.","4,5 cm entsprechen 0,45 m.","Die schmalere Stelle verfehlt die Vorgabe um 0,06 m.","4,5 cm entsprechen genau dem Mindestmaß.","Beide Wege genügen, solange die breite Stelle 4,5 cm erreicht.","4,2 cm entsprechen 1,20 m."],"answer":[0,2,3],"why":"Multipliziere das Planmaß mit 20. 84 cm fehlen 6 cm zu 90 cm. 4,5 cm entsprechen 90 cm. Die Regel gilt an der engsten Stelle und auf dem restlichen Weg.","hint":"Rechne zuerst von Plan-Zentimetern in wirkliche Zentimeter um.","steps":"Vergleiche die Ergebnisse mit 90 cm. Achte auf die engste Stelle.","example":"3 cm auf dem Blatt entsprechen bei diesem Maßstab 60 cm im Laden.","c":3,"sourceRefs":["M2","M4"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Papiermodelle für den Test","scene":"Du baust die Anordnung im Maßstab 1:20. Das Rollregal misst 1,00 m × 0,40 m, der Tisch 0,80 m × 0,55 m. Für das Rad sind 1,80 m × 0,65 m angesetzt.","ask":"Welche Zuschnitte sind richtig?","options":["Rollregal: 10,0 cm × 4,0 cm.","Tisch: 4,0 cm × 2,75 cm.","Fahrrad: 9,0 cm × 3,25 cm.","Rollregal: 5,0 cm × 2,0 cm.","Tisch: 4,0 cm × 4,5 cm.","Fahrrad: 18,0 cm × 6,5 cm."],"answer":[1,2,3],"why":"Teile die wirklichen Zentimeter jeweils durch 20. So ergeben sich 5,0 × 2,0 cm, 4,0 × 2,75 cm und 9,0 × 3,25 cm.","hint":"Verwende dieselbe Rechnung für jede einzelne Seite.","steps":"Schreibe alle wirklichen Längen in Zentimetern auf und teile sie jeweils durch 20.","example":"Für 60 cm wirkliche Länge wären im Modell 3 cm nötig.","c":3,"sourceRefs":["M2","M4"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine eigene Platzierung korrigieren","scene":"Übungsvariante: Dein Regal reicht im Plan von x = 1,00 bis x = 2,00 m und von y = 2,00 bis y = 2,40 m. Hauptdurchgang und Aktionsfläche treffen bei x = 1,20 m aufeinander. Ein Teammitglied weist auf eine Überschneidung hin.","ask":"Welche Reaktion verbessert deinen Entwurf?","options":["Das Regal unverändert lassen und nur die Bedienseite drehen.","Den Plan korrigieren, weil das Regal 0,20 m in den Hauptdurchgang ragt.","Den Standort beibehalten, weil mehr als die Hälfte des Regals auf der Aktionsfläche liegt.","Nach dem Versetzen den freien Weg zur Bedienseite erneut prüfen.","Die Grenze der Aktionsfläche verschieben, damit das Regal vollständig hineinpasst.","Den Einwand zurückweisen, weil der Hauptdurchgang im Entwurf anders eingefärbt ist."],"answer":[1,3],"why":"Von x = 1,00 bis 1,20 m stehen 20 cm des Regals im Gang. Die Korrektur muss die Überschneidung entfernen und den Zugriff am neuen Standort sichern.","hint":"Überprüfe die Rückmeldung am eigenen Plan.","steps":"Vergleiche die x-Werte und kontrolliere nach einer Korrektur auch die neue Bedienseite.","example":"Ein Regal kann größtenteils in der richtigen Fläche liegen und trotzdem eine feste Grenze überschreiten.","c":1,"sourceRefs":["M1","M2"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welcher Entwurf eignet sich für den Probelauf?","scene":"Übungsvariante: Entwurf A hat einen freien Vorführplatz von 2,10 m × 1,30 m. Beim Vorführen misst der schmalste Weg zur Bedienseite 0,85 m. In Entwurf B misst der Vorführplatz 2,00 m × 1,35 m, der dortige Weg überall mindestens 0,95 m. Hauptdurchgang und Tresenzugang bleiben in beiden Entwürfen frei.","ask":"Welche Folgerungen treffen zu?","options":["A erfüllt die Wegregel, weil die 0,85 m nur während der Vorführung gemessen wurden.","Beide Vorführplätze erfüllen das Mindestmaß.","B ist nach den vorliegenden Maßen besser geeignet.","A bietet am schmalsten Punkt 0,05 m Reserve zur Wegvorgabe.","B muss nichts an der Erreichbarkeit der verpackten Ware überprüfen.","In A verfehlt der Weg zur Bedienseite das Mindestmaß."],"answer":[1,2,5],"why":"Beide Vorführplätze sind groß genug. Bei A fehlen beim Greifen 0,05 m Wegbreite. B erfüllt die genannten Maße. Die tatsächlichen Handgriffe prüfst du anschließend im Probelauf.","hint":"Trenne Vorführplatz, Wegbreite und praktische Greifprobe.","steps":"Bewerte beide Entwürfe jeweils mit denselben Maßen und halte offene Fragen fest.","example":"Ein Maß kann erfüllt sein und dennoch einen Praxistest erforderlich machen.","c":2,"sourceRefs":["M2","M5"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Artikel so gruppieren, dass die Beratung gelingt","scene":"Übungsvariante: Dein Team zeichnet die Warenplätze und will die Zusammenstellung kurz erklären.","ask":"Welche Begründungen tragen fachlich?","options":["Musterlicht und verpackte Lichtsets bekommen unterschiedliche, einander zugeordnete Plätze.","Die Minipumpe soll beim Vorführen am Ventil griffbereit sein.","Das Schloss steht wegen seiner Masse am höchsten, damit es sich aus der Beratungszone greifen lässt.","Sattelüberzug und Rahmentasche müssen an einer einzigen Stelle sichtbar sein, weil beide aus Textil bestehen.","Beim Taschenmuster ist Platz zum Anfassen und Öffnen ein sinnvolles Kriterium.","Die verpackte Ware kann beim Versuch überall stehen, wenn die freien Wege eingezeichnet sind."],"answer":[0,1,4],"why":"Die Platzierung folgt der tatsächlichen Kundenfrage. Licht braucht Muster und erreichbare Schachteln, die Pumpe Nähe zur Ventilvorführung und die Tasche ein zugängliches leeres Muster.","hint":"Lies die Kundenaussage und die Vorgabe je Artikel gemeinsam.","steps":"Prüfe, was während der Beratung gegriffen, befestigt oder geöffnet wird.","example":"Eine gut sichtbare Ware ist noch nicht automatisch gut vorführbar.","c":0,"sourceRefs":["M2","M3"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welche Wege fehlen im Rollenspiel?","scene":"Im Test zeigt das Team die Lichtmontage am Kundinnenrad. Die zweite Rolle muss mit einem Rad zur Werkstatt. Eine dritte Person verkauft am Tresen weiter.","ask":"Welche Beobachtungen helfen, den Ablauf zu verbessern?","options":["Ob das Kundinnenrad am Eingang einen guten ersten Eindruck macht.","Ob die beratende Person beim Vorführen zur verpackten Ware kommt.","Ob das zweite Rad den Hauptdurchgang nutzen kann, ohne dass der Versuch unterbrochen wird.","Ob der Weg zum Tresen im Ablauf frei bleibt.","Ob die beratende Person die Form des Bügelschlosses genauer erklären kann als andere.","Ob sich das Vorführrad auch außerhalb der Ladenöffnungszeit reinigen lässt."],"answer":[1,2,3],"why":"Die Probe soll Greifen, Vorbeischieben und Tresenzugang gleichzeitig abdecken. Eine beobachtete Blockade zeigt, wo der Plan nachgeschärft werden muss.","hint":"Achte auf die drei Personen und ihre jeweiligen Wege.","steps":"Führe die Tätigkeiten zeitgleich aus. Markiere Stellen, an denen jemand anhält oder ausweicht.","example":"Ein freier Gang in einer Probe ohne zweites Fahrrad reicht als Nachweis für Begegnungen kaum aus.","c":2,"sourceRefs":["M2","M4","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Minipumpe am richtigen Ort erklären","scene":"Das Vorführrad hat ein Sclaverandventil. Eine Person fragt nach der Minipumpe P50 und möchte sehen, wie die Verkäuferin sie ansetzt.","ask":"Welche Schritte passen zur Beratung bei Block?","options":["Die Pumpe wird am Ventil des Vorführrads angesetzt.","Die Verkäuferin zeigt nur, wo die Pumpenverpackung liegt.","Beim Zeigen bleiben der Hauptdurchgang und der Weg zur Ware frei.","Eine erfolgreiche Vorführung an diesem Rad bestätigt automatisch die Eignung für jedes Ventil.","Das Personal muss P50 vor oder während der Beratung am Warenplatz erreichen können.","Die Vorführung findet am Tresen statt, weil der im Plan fest eingezeichnet ist."],"answer":[0,2,4],"why":"Das Rad ermöglicht eine konkrete Demonstration am Sclaverandventil. Ein anderer Ventiltyp braucht eine eigene Eignungsprüfung. Der Plan muss die Erreichbarkeit von P50 und der Wege sichern.","hint":"Prüfe, welches Ventil in M2 genannt wird und was die Kundenfrage in M3 verlangt.","steps":"Überlege getrennt, wo die Pumpe gegriffen und wo sie angesetzt wird.","example":"Ein Muster an einem Rad zeigt zuerst nur, was an genau diesem Rad möglich ist.","c":0,"sourceRefs":["M2","M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Rückmeldung zu einem schwer lesbaren Plan","scene":"Übungsvariante: Auf der Skizze fehlen die Bedeutung der Pfeile, die Artikelkennzeichen und die Maße an einer Engstelle.","ask":"Welche Ergänzungen erleichtern die Prüfung?","options":["Alle Pfeile mit dem Wort „Aktion“ beschriften.","Bedienseiten und Wege mit unterscheidbaren Zeichen und einer Legende darstellen.","Die Engstelle mit Maß und Bezug zum richtigen Weg kennzeichnen.","Die fehlenden Artikelkennzeichen als M1 bis M6 eintragen.","L10, P50 und die anderen Artikel an ihren Warenplätzen kennzeichnen.","Auf dem Plan nur die Maße der Gesamtfläche ergänzen."],"answer":[1,2,4],"why":"Eine klare Legende unterscheidet Bedienseiten und Wege. Eingetragene Maße zeigen den Engpass, Produktcodes kennzeichnen die Warenplätze. M1–M6 sind Materialverweise, keine Produkte.","hint":"Leite aus jeder fehlenden Angabe eine konkrete Ergänzung ab.","steps":"Prüfe nacheinander: Zeichen verstehen, Engstelle messen, Produkt finden.","example":"Ein Maß direkt an der betreffenden Stelle ist leichter zu prüfen als eine unverbundene Zahl neben dem Titel.","c":4,"sourceRefs":["M1","M3","M4","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Einwand führt zur Nachbesserung","scene":"Übungsvariante: Ein Prüfergebnis lautet: „Die Kundin kann vorbeikommen, aber das Vorderrad steht dabei vor dem Regal. Eure Verkäuferin kommt nicht an L10.“","ask":"Welche Reaktionen verbessern den Entwurf nachvollziehbar?","options":["Die für die Blockade verantwortliche Position im Plan festhalten.","Die Rückmeldung als Geschmacksfrage behandeln und ignorieren.","Die Position des Vorführplatzes oder des Regals so überprüfen, dass Bedienseite und Wege nutzbar sind.","Den Pfeil zum Lichtregal entfernen, weil der Zugriff im Test nicht geklappt hat.","Erneut eine Beratung mit Zugriff auf L10 nachspielen und das Ergebnis notieren.","Die im Test blockierte Bedienseite in beiden Entwürfen vergleichen."],"answer":[0,2,4,5],"why":"Greifproblem und verursachende Position gehören in den Plan. Der Vergleich zeigt mögliche Änderungen. Eine erneute Probe mit der beratenden Rolle prüft, ob die Schachteln erreichbar bleiben.","hint":"Beziehe Rückmeldung, Änderung und erneute Probe auf denselben Arbeitsschritt.","steps":"Stell den Ablauf nach: Wann und wo soll die Verkäuferin an L10 kommen?","example":"Eine Äußerung wie „Regal verschoben“ gewinnt durch eine anschließende Beobachtung an Aussagekraft.","c":1,"sourceRefs":["M2","M4","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Flächenvergleich mit derselben Messlatte","scene":"Übungsvariante: Zwei Teams vergleichen alternative Beratungsflächen. Das erste zeigt nur ein erfolgreiches Gespräch zum Licht, das zweite nur ein knappes Maß am Tresen.","ask":"Wie wird der Vergleich fair und aussagekräftig?","options":["Beim ersten Entwurf ausschließlich den Vorführplatz bewerten.","In beiden Entwürfen dieselben Wege und Mindestmaße prüfen.","In beiden Entwürfen Licht- und Pumpenberatung erproben.","Jeden Entwurf nach dem bewerten, was das jeweilige Team bereits gut gezeigt hat.","Bei beiden Varianten notieren, ob das Personal die Ware im Versuch erreicht.","Nur das optisch aufgeräumtere Modell als Grundlage nehmen."],"answer":[1,2,4],"why":"Die gleichen Maße, Testszenen und Beobachtungspunkte machen die Entwürfe vergleichbar. Sonst kann ein Vorteil nur daran liegen, dass jeweils andere Dinge geprüft wurden.","hint":"Achte darauf, dass beide Entwürfe dieselben Anforderungen erfüllen müssen.","steps":"Lege gemeinsame Messpunkte und Tests fest, bevor du eine Variante empfiehlst.","example":"Eine Probe mit Licht testet einen anderen Griffweg als eine Probe mit der Minipumpe.","c":3,"sourceRefs":["M2","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Den Kurzpitch mit Belegen füllen","scene":"Übungsvariante: Im Pitch bleiben zwei Minuten. Die Ladenleitung möchte verstehen, warum ihr eure Anordnung empfehlt.","ask":"Welche Inhalte erfüllen das Ziel?","options":["Den Standort des Vorführplatzes im Plan zeigen.","Für die Empfehlung nur sagen: „Unser Plan ist übersichtlicher.“","Eine Messung oder eine konkrete Beobachtung aus der Probe nennen.","Die Preise aller fünf Artikel auflisten.","Ein Zwischenergebnis zeigen und sagen, wie es zur Entscheidung beigetragen hat.","Alle grundlegenden Begriffe ohne Bezug zum Plan aufsagen."],"answer":[0,2,4],"why":"Zeige die gewählte Anordnung, stütze sie mit einem konkreten Beleg und erkläre, wie das Zwischenergebnis beim Entscheiden geholfen hat.","hint":"Orientiere dich an den drei Schritten im Pitchauftrag.","steps":"Kläre vorab: Was zeigen wir? Was belegt unsere Wahl? Was hat uns beim Entscheiden geholfen?","example":"„Auf dem Papier sind hier 4,5 cm frei“ ist ein prüfbarer Beleg.","c":4,"sourceRefs":["M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Mit einem Rollregal neu planen","scene":"Übungsvariante: Am Morgen der Aufbauprobe fällt ein Rollregal aus. Ein Rollregal und der schmale Tisch bleiben. Das Aktionssortiment und die Vorgaben zu Wegen, Tresen und Vorführplatz gelten weiter.","ask":"Wie verschaffst du dir eine Grundlage für den neuen Aufbau?","options":["Ich zeichne die nutzbaren Flächen neu ein und markiere, welche Maße der bisherige Entwurf weiterhin einhält.","Ich gehe mit der Verkäuferin den Ablauf für Licht und Minipumpe durch und notiere, was sie wann greifen muss.","Ich halte fest, welche Möbel jetzt verfügbar sind, und markiere die Flächen, die beim Umbau geschützt bleiben.","Ich lege die zwei Möbel im Modell und messe nach, welche Bereiche unverändert für Kunden und Personal frei bleiben.","Ich beziehe Werkstatt und Verkauf ein und sammle, an welchen Stellen ihre Wege im Umbau abgesichert sein müssen.","Ich liste zuerst die unveränderlichen Anforderungen auf und lege fest, welche Aufbauschritte bei einem Regal neu geprüft werden."],"consequences":["Deine Skizze gibt dir Vergleichsmaße für den alten und den neuen Aufbau.","Du weißt, welche Warenplätze aus Sicht der Beratung funktionieren müssen.","Du beginnst mit geklärten Ressourcen und geschützten Flächen.","Im Modell siehst du, wo sich durch das fehlende Regal Wege ändern.","Die Anforderungen beider Arbeitsbereiche fließen früh in die Planung ein.","Du hast eine Reihenfolge für die Prüfung und kannst Pflichtbedingungen im Blick behalten."],"why":"Ein fehlendes Regal ändert die Platzierung. Wegbreiten, Vorführfläche und freier Tresenzugang gelten im neuen Aufbau weiter.","hint":"Trenne geänderte Mittel und unveränderte Anforderungen.","steps":"Lege zuerst fest, welchen Blickwinkel du bei den nächsten Entscheidungen weiterverfolgst.","example":"Eine Modellmessung, ein Gespräch und eine Liste der Vorgaben liefern unterschiedliche Informationen.","c":3,"sourceRefs":["M1","M2","M3"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Fünf Artikel auf zwei Möbel verteilen","scene":"Das Team entwirft neue Warenplätze. Bei L10 bleiben Muster und Schachteln nötig. P50 soll am Rad gezeigt werden. Das S20 gehört in die untere Zone. Auch Rahmentasche und Sattelüberzug bleiben Teil der Aktion.","ask":"Wie entwickelst du die neue Platzierung weiter?","options":["Ich vergleiche zwei Warenplatzskizzen und trage an beiden ein, ob L10 und P50 beim Vorführen erreichbar sind.","Ich lasse eine Kollegin Licht und Pumpe bei einer gestellten Beratung greifen und passe bestätigte Problemstellen an.","Ich reserviere die untere Regalzone für das Schloss und schließe den Vorführplatz beim Verteilen der Packungen als Lagerfläche aus.","Ich protokolliere im Modell, von welchem Warenplatz das Personal jeweils zugreift und wie es dabei den Gang nutzt.","Ich lasse eine zweite Person mit dem Fahrrad vorbeigehen und frage sie, an welchen Stellen sich das Greifen und ihre Bewegung in die Quere kommen.","Ich teile Regal und Tisch nach Funktion ein und kontrolliere jeden neuen Stellplatz auf freien Zugang, Vorführfläche und Tresen."],"consequences":["Mit denselben Zugriffspunkten kannst du zwei Warenpläne vergleichen.","Die Rückmeldung der Kollegin zeigt, welche Handgriffe im neuen Aufbau funktionieren.","Die verpflichtenden Plätze und Freiflächen bleiben bei der Verteilung geschützt.","Deine Aufzeichnungen verknüpfen die Platzierung mit dem tatsächlichen Weg.","Du erfasst eine Engstelle auch aus Sicht der vorbeigehenden Kundschaft.","Die Zuordnung gibt dem Aufbau eine klare Reihenfolge und schützt die Pflichtflächen."],"why":"Alle fünf Artikel bleiben vorgesehen. Greifbarkeit, Vorführung und freie Wege müssen zusammen funktionieren.","hint":"Greif deinen Blickwinkel aus der ersten Entscheidung wieder auf.","steps":"Prüfe, wie dein neuer Warenplatz die jeweils benötigte Nutzung ermöglicht.","example":"Eine Schachtel und ein Muster desselben Artikels müssen unterscheidbar abgelegt werden.","c":0,"sourceRefs":["M2","M3"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Gleichzeitig greifen und vorbeigehen","scene":"Bei der Probe greift die Verkäuferin zum verpackten Lichtset. Genau dann nähert sich eine Person mit Fahrrad auf dem Weg zur Werkstatt. Im neuen Entwurf ist an dieser Stelle wenig Bewegungsraum.","ask":"Wie klärst du, ob und wo der Aufbau angepasst werden muss?","options":["Ich messe am kritischen Punkt den freien Weg während der Szene und markiere das Ergebnis im Plan.","Ich lasse beide beteiligten Rollen schildern, an welcher Bewegung sie hängen bleiben, und spiele die Szene mit einer Änderung erneut durch.","Ich kontrolliere die dort geltende Wegvorgabe und lege vor dem nächsten Versuch fest, wohin das Möbel bei zu knappem Abstand rückt.","Ich trage den Weg der Verkäuferin und den des Fahrrads im Modell ein und prüfe am Schnittpunkt den geringsten freien Abstand.","Ich sehe eine zweite Probe aus der Sicht der wartenden Person an und hole gezielt Rückmeldung ein, wann sie vorbeikommt.","Ich halte Hauptdurchgang und Greifweg als getrennte Anforderungen fest und teile den Umbau und anschließenden Test im Team zu."],"consequences":["Die Messung macht die vermutete Engstelle nachprüfbar.","Beide Rollen können erklären, welche Bewegung der Umbau verbessern soll.","Eine vorher vereinbarte Veränderung macht den nächsten Test zielgerichtet.","Du siehst, wo die zwei Bewegungen gleichzeitig Raum beanspruchen.","Die Rückmeldung zeigt, ob die Kundschaft die Verbindung zur Werkstatt nutzen kann.","Alle prüfen dieselben Anforderungen und kennen ihre Aufgabe beim Umbau."],"why":"Der Aufbau muss auch dann funktionieren, wenn Vorführung, Warenzugriff und eine weitere Bewegung gleichzeitig stattfinden.","hint":"Wo hat dein bisheriger Arbeitsweg eine Beobachtung, eine Rückmeldung oder eine Vorgabe gesammelt?","steps":"Untersuche dieselbe Stelle während der Nutzung, nicht nur im leeren Plan.","example":"Eine freie Linie vor der Probe belegt noch keinen freien Weg mit zwei Rädern.","c":2,"sourceRefs":["M2","M4","M5"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Rückweg zum Tresen klären","scene":"Das Team findet eine günstigere Regalstellung. Beim Durchspielen kommt die Verkäuferin an L10. Eine neue Frage bleibt offen: Erreicht die Kundschaft den Tresen auch während einer Pumpenvorführung?","ask":"Wie ergänzt du die bisherige Prüfung?","options":["Ich markiere den Tresenzugang im neuen Plan und notiere, an welchem Punkt ich ihn bei der Pumpenvorführung geprüft habe.","Ich lasse eine Person während der Pumpenvorführung zum Tresen gehen und frage sie danach, an welcher Stelle sie warten musste oder gut durchkam.","Ich nehme den freien Tresenzugang als eigene Bedingung in die Aufbauprüfung auf und vereinbare einen Prüfschritt vor der Freigabe.","Ich prüfe mit dem Fahrradmodell, ob sich Vorführfläche und Zugang im Plan überschneiden, und halte die Stelle fest.","Ich bespreche die Variante mit der Person am Tresen und der beratenden Person und lasse beide ihren Weg gleichzeitig nachspielen.","Ich ermittle, welche Platzänderung möglich ist, wenn der Zugang versperrt ist, und weise die Verantwortung für die erneute Probe zu."],"consequences":["Du gibst dem Team einen verorteten Beleg für den Tresenzugang.","Du erfährst, was der neue Aufbau für eine Person auf dem Weg zum Tresen bedeutet.","Der Tresenzugang wird ein überprüfbarer Teil der Freigabe.","Der Plan zeigt den möglichen Konflikt zwischen Vorführung und Zugang.","Die Probe verbindet die Perspektiven am Tresen und in der Beratung.","Für einen weiteren Umbau sind ein gangbarer Schritt und seine Prüfung vereinbart."],"why":"Der Tresen bleibt fest. Eine nutzbare Bedienseite am Regal beantwortet die offene Frage zum Tresenzugang noch nicht.","hint":"Bleib beim Schwerpunkt deines bisherigen Prüfwegs.","steps":"Ergänze die fehlende Nutzung, ohne deine bisherigen Prüfpunkte wegzulassen.","example":"Licht greifen und den Tresen erreichen sind in diesem Plan unterschiedliche Aufgaben.","c":1,"sourceRefs":["M1","M2","M5"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die überarbeitete Fassung lesbar machen","scene":"Euer Aufbau ist im Modell geprüft. Die Ladenleitung bekommt den Plan ohne eure mündliche Erklärung. Das Display zeigt nur einen kleinen Ausschnitt der Zeichnung.","ask":"Wie sicherst du deinen Arbeitsweg im Plan ab?","options":["Ich ergänze die entscheidenden Messstellen und verknüpfe die Maße im Plan mit kurzen Prüfanmerkungen.","Ich lasse jemand aus dem Verkauf den Plan ohne Hilfe lesen und passe die Beschriftung nach einer konkreten Rückfrage an.","Ich trage Freiflächen und die Position des feststehenden Tresens als feste Vorgaben mit klaren Linien in den Plan ein.","Ich markiere bei der neuen Warenplatzanordnung einen überprüften Laufweg und lege mit der Legende offen, auf welchen Test er sich stützt.","Ich lasse eine Person aus der Kundschaftsrolle nur mit der Legende den Werkstattweg und den Platz zum Vorführen auseinanderhalten.","Ich beschrifte die Aufbaureihenfolge und verweise im Plan auf die Stellen, die vor der Öffnung frei gehalten werden müssen."],"consequences":["Deine Maßangaben bleiben mit dem geprüften Ort verbunden.","Ein unabhängiger Lesetest zeigt, an welcher Information der Plan verständlicher werden muss.","Die Leitung erkennt feste Grenzen und kann die Möbel passend dazu aufstellen.","Test, Weg und Planzeichen sind auch ohne mündliche Erläuterung verbunden.","Die Rückmeldung zeigt, ob die Legende die Wege ausreichend unterscheidet.","Die Aufbauhilfe verbindet Möbelpositionen mit der letzten Kontrolle."],"why":"Ein lesbarer Plan zeigt Artikelplätze, Maße und die Funktion seiner Zeichen. Die entscheidenden Änderungen müssen auffindbar bleiben.","hint":"Prüfe, was dein eigener Arbeitsweg der Ladenleitung nachvollziehbar machen soll.","steps":"Wähle eine Darstellung, die die Annahme, Messung oder Vereinbarung am richtigen Ort verankert.","example":"Eine Pfeillegende kann die Bewegungsrichtung und die Greifseite klar unterscheiden.","c":4,"sourceRefs":["M1","M4","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den neuen Aufbau empfehlen","scene":"Die Ladenleitung fragt: „Können wir morgen mit einem Rollregal öffnen?“ Ihr zeigt euren Plan und nennt, was vor dem echten Aufbau noch geprüft werden muss.","ask":"Welche Empfehlung schließt deinen bisherigen Weg stimmig ab?","options":["Ich zeige den Vergleich alter und neuer Maße und begründe die Empfehlung mit dem entscheidenden Prüfergebnis.","Ich nenne, was sich durch die Rückmeldungen aus Beratung, Tresen und Kundenweg verbessert hat, und vereinbare eine kurze Rückmeldung aus dem echten Aufbau.","Ich zeige im Plan die Möbel, die Freiflächen und die noch nötige Kontrolle, damit die Leitung den Aufbau in der richtigen Reihenfolge durchführen kann.","Ich zeige die Stelle im Plan, an der sich der konfliktreiche Griffweg verbessert hat, und nenne die noch offene Messung im aufgebauten Laden.","Ich zeige, wie eine beobachtete Rollenprobe die Variante verändert hat, und benenne, wer beim Aufbau das Ergebnis noch einmal prüft.","Ich fasse zusammen, welche festen Ladenregeln erfüllt sein müssen, und lege den offenen Freigabeschritt mit zuständiger Person fest."],"consequences":["Deine Empfehlung ist am vermessenen Unterschied nachvollziehbar.","Die Beteiligten erkennen, wie ihre Beobachtungen in die Entscheidung eingeflossen sind.","Die Leitung kann unmittelbar erkennen, was aufgebaut und danach kontrolliert werden muss.","Du zeigst eine konkrete Verbesserung und hältst die Grenze des Modelltests offen.","Die Probe wird zur nachvollziehbaren Grundlage mit einer geklärten Nachkontrolle.","Die Ladenleitung weiß, unter welchen Bedingungen sie entscheiden kann."],"why":"Der Plan kann eine Empfehlung tragen. Der Test im echten Laden bleibt bei geänderten Möbeln ein eigener Schritt.","hint":"Verbinde die Empfehlung mit genau der Grundlage, die du vorher aufgebaut hast.","steps":"Zeige kurz Ergebnis, Begründung und noch offene Prüfung.","example":"Eine Empfehlung kann unter der Bedingung ausgesprochen werden, dass eine markierte Engstelle im echten Aufbau frei bleibt.","c":4,"sourceRefs":["M2","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.3 · Waren im Fahrradfachgeschäft präsentieren","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]}];
